/* ===================== BÀI 40 · LCD ký tự và menu ===================== */
/* Bài 40 · LCD ký tự và menu (AMTS-EMB-001-M10-L04, MC51-040) — sinh bởi tools/author/mcu8051/l40.py, không sửa tay.
   Ví dụ cho trình mô phỏng 8051 và bài tập chấm tự động (đề, code mẫu, bộ thử). Lời giải không nằm ở đây. */
const PR40=[{"label":"Ví dụ: Khởi tạo 8 bit và in một dòng","code":"; Ví dụ 1: khởi tạo LCD 16x2 chế độ 8 bit, in một dòng.\n; D0…D7 = P2, RS = P3.5, RW = P3.6, E = P3.7 (giả định nối dây)\n        ORG     0000H\n        CLR     P3.6                    ; RW = 0: chỉ ghi\n        MOV     A,#38H                  ; 8 bit, 2 dòng, chữ 5x8\n        ACALL   LCMD\n        MOV     A,#0CH                  ; bật hiển thị, tắt con trỏ\n        ACALL   LCMD\n        MOV     A,#06H                  ; ghi xong thì AC tăng 1\n        ACALL   LCMD\n        MOV     A,#01H                  ; xóa màn hình, AC = 0\n        ACALL   LCMD\n        MOV     R6,#4                   ; lệnh xóa cần 1,52 ms: chờ 2 ms\n        ACALL   DMS\n        MOV     DPTR,#MSG\nNEXT:   CLR     A\n        MOVC    A,@A+DPTR               ; ký tự kế tiếp\n        JZ      DONE                    ; 0 = hết chuỗi\n        ACALL   LDAT\n        INC     DPTR\n        SJMP    NEXT\nDONE:   SJMP    $\n; ---- ghi lệnh (LCMD) hoặc ký tự (LDAT) trong A ----\nLCMD:   CLR     P3.5                    ; RS = 0: lệnh\n        SJMP    LWR\nLDAT:   SETB    P3.5                    ; RS = 1: ký tự\nLWR:    MOV     P2,A                    ; dữ liệu ra trước\n        SETB    P3.7                    ; E = 1\n        CLR     P3.7                    ; E = 0: LCD chốt ở sườn xuống\n        MOV     R7,#20                  ; 1 + 20 x 2 = 41 chu kỳ > 37 µs\n        DJNZ    R7,$\n        RET\n; ---- chờ R6 x 499 + 2 chu kỳ (khoảng R6 x 0,5 ms) ----\nDMS:    MOV     R7,#248\n        DJNZ    R7,$\n        DJNZ    R6,DMS\n        RET\nMSG:    DB      'AMTS 8051',0\n        END\n","note":"4 lệnh × 52 chu kỳ + chờ xóa 2 001 + 9 ký tự × 58 = 2 739 chu kỳ. LCD hiện “AMTS 8051”. Theo dõi P3.5 (RS) đổi 0 → 1 khi chuyển từ lệnh sang ký tự, và P2 mang mã ASCII (41H = 'A').","dev":{"lcd":true},"fosc":12000000,"speed":"real"},{"label":"Lỗi: Không chờ sau lệnh xóa màn hình","code":"; Ví dụ 2 (LỖI): như ví dụ 1 nhưng không chờ sau lệnh xóa\n; 01H. LCD còn bận 1,52 ms nên bỏ qua các ký tự gửi tới.\n        ORG     0000H\n        CLR     P3.6                    ; RW = 0: chỉ ghi\n        MOV     A,#38H                  ; 8 bit, 2 dòng, chữ 5x8\n        ACALL   LCMD\n        MOV     A,#0CH                  ; bật hiển thị, tắt con trỏ\n        ACALL   LCMD\n        MOV     A,#06H                  ; ghi xong thì AC tăng 1\n        ACALL   LCMD\n        MOV     A,#01H                  ; xóa màn hình, AC = 0\n        ACALL   LCMD\n                                        ; (thiếu: chờ 1,52 ms sau lệnh xóa)\n        MOV     DPTR,#MSG\nNEXT:   CLR     A\n        MOVC    A,@A+DPTR               ; ký tự kế tiếp\n        JZ      DONE                    ; 0 = hết chuỗi\n        ACALL   LDAT\n        INC     DPTR\n        SJMP    NEXT\nDONE:   SJMP    $\n; ---- ghi lệnh (LCMD) hoặc ký tự (LDAT) trong A ----\nLCMD:   CLR     P3.5                    ; RS = 0: lệnh\n        SJMP    LWR\nLDAT:   SETB    P3.5                    ; RS = 1: ký tự\nLWR:    MOV     P2,A                    ; dữ liệu ra trước\n        SETB    P3.7                    ; E = 1\n        CLR     P3.7                    ; E = 0: LCD chốt ở sườn xuống\n        MOV     R7,#20                  ; 1 + 20 x 2 = 41 chu kỳ > 37 µs\n        DJNZ    R7,$\n        RET\nMSG:    DB      'AMTS 8051',0\n        END\n","note":"Bỏ đoạn chờ sau lệnh 01H: 9 ký tự đến trong khoảng 520 µs sau lệnh xóa, khi LCD còn bận 1 520 µs, nên đều bị bỏ qua — màn hình trống và có cảnh báo “LCD còn bận”. Sửa: chờ ≥ 1,52 ms (ví dụ 1) hoặc đọc BF (ví dụ 3).","dev":{"lcd":true},"fosc":12000000,"speed":"real"},{"label":"Ví dụ: Chờ cờ bận BF có giới hạn","code":"; Ví dụ 3: chờ bằng cờ bận BF (đọc D7 khi RW = 1), có giới\n; hạn 256 lần đọc. LCD không trả lời: 32H = 01H, dừng.\n        ORG     0000H\n        MOV     32H,#0                  ; 0 = tốt, 1 = LCD không trả lời\n        MOV     R0,#0                   ; R0 = vị trí trong bảng lệnh\nCMDS:   MOV     A,R0\n        MOV     DPTR,#INIT\n        MOVC    A,@A+DPTR               ; 38H, 0CH, 06H, 01H, 0 = hết\n        JZ      TEXT\n        ACALL   LCMD                    ; chờ BF rồi ghi lệnh\n        JC      FAIL\n        INC     R0\n        SJMP    CMDS\nTEXT:   MOV     DPTR,#MSG\nNEXT:   CLR     A\n        MOVC    A,@A+DPTR\n        JZ      DONE\n        ACALL   LDAT\n        JC      FAIL\n        INC     DPTR\n        SJMP    NEXT\nFAIL:   MOV     32H,#1                  ; báo lỗi thay vì treo\nDONE:   SJMP    $\n; ---- ghi A sau khi LCD rảnh; C = 1 nếu quá giới hạn ----\nLCMD:   CLR     P3.5                    ; RS = 0\n        SJMP    LWR\nLDAT:   SETB    P3.5                    ; RS = 1\nLWR:    MOV     R2,A                    ; giữ byte cần ghi\n        MOV     C,P3.5\n        MOV     F0,C                    ; nhớ RS\n        ACALL   WAIT\n        JC      LOUT                    ; LCD không rảnh\n        MOV     C,F0\n        MOV     P3.5,C                  ; trả RS\n        MOV     P2,R2\n        SETB    P3.7\n        CLR     P3.7                    ; chốt ở sườn xuống\n        CLR     C                       ; C = 0: đã ghi\nLOUT:   RET\n; ---- đọc BF tới khi = 0, tối đa 256 lần (7 chu kỳ/lần) ----\nWAIT:   MOV     P2,#0FFH                ; chân dữ liệu làm ngõ vào\n        CLR     P3.5                    ; RS = 0, RW = 1: đọc BF và AC\n        SETB    P3.6\n        MOV     R3,#0                   ; 256 lần\nWT:     SETB    P3.7                    ; E = 1: LCD đưa BF ra D7\n        MOV     A,P2\n        CLR     P3.7\n        JNB     ACC.7,WOK               ; BF = 0: rảnh\n        DJNZ    R3,WT\n        CLR     P3.6\n        SETB    C                       ; quá 256 lần: lỗi\n        RET\nWOK:    CLR     P3.6                    ; RW = 0: ghi\n        CLR     C\n        RET\nINIT:   DB      38H,0CH,06H,01H,0\nMSG:    DB      'BF OK',0\n        END\n","note":"Có LCD: mỗi lần chờ chỉ vài lần đọc, riêng sau lệnh xóa khoảng 1 520 / 7 ≈ 218 lần; hiện “BF OK”, 32H = 00H. Khi LCD không cắm (đã thử trên s51, máy không có LCD): BF đọc 1 mãi, sau 256 lần chương trình báo 32H = 01H ở chu kỳ 1 830 thay vì treo.","dev":{"lcd":true},"fosc":12000000,"speed":"real"},{"label":"Ví dụ: Chế độ 4 bit trên P2.4…P2.7","code":"; Ví dụ 4: LCD chế độ 4 bit, chỉ nối D4…D7 = P2.4…P2.7.\n; Khởi tạo bằng lệnh: 3 lần 3xH, rồi 2xH (sang 4 bit), 28H.\n        ORG     0000H\n        CLR     P3.6                    ; RW = 0\n        CLR     P3.5                    ; RS = 0: lệnh\n        MOV     R6,#32                  ; chờ sau cấp nguồn: 16 ms > 15 ms\n        ACALL   DMS\n        MOV     A,#30H                  ; lần 1 (LCD còn ở 8 bit)\n        ACALL   NIB\n        MOV     R6,#10                  ; chờ > 4,1 ms\n        ACALL   DMS\n        MOV     A,#30H                  ; lần 2\n        ACALL   NIB\n        MOV     R6,#1                   ; chờ > 100 µs\n        ACALL   DMS\n        MOV     A,#30H                  ; lần 3\n        ACALL   NIB\n        ACALL   W40\n        MOV     A,#20H                  ; sang 4 bit (một nửa byte)\n        ACALL   NIB\n        ACALL   W40\n        MOV     A,#28H                  ; từ đây mỗi byte = 2 nửa\n        ACALL   LCMD                    ; 4 bit, 2 dòng, 5x8\n        MOV     A,#0CH\n        ACALL   LCMD\n        MOV     A,#06H\n        ACALL   LCMD\n        MOV     A,#01H\n        ACALL   LCMD\n        MOV     R6,#4\n        ACALL   DMS                     ; xóa: chờ 2 ms\n        MOV     DPTR,#MSG\nNEXT:   CLR     A\n        MOVC    A,@A+DPTR\n        JZ      DONE\n        ACALL   LDAT\n        INC     DPTR\n        SJMP    NEXT\nDONE:   SJMP    $\n; ---- một byte = nửa cao rồi nửa thấp, mỗi nửa một xung E ----\nLCMD:   CLR     P3.5\n        SJMP    LWR\nLDAT:   SETB    P3.5\nLWR:    ACALL   NIB                     ; nửa cao (A.7…A.4 ra P2.7…P2.4)\n        SWAP    A\n        ACALL   NIB                     ; nửa thấp\nW40:    MOV     R7,#20                  ; chờ 41 chu kỳ\n        DJNZ    R7,$\n        RET\nNIB:    MOV     P2,A                    ; P2.0…P2.3 không nối LCD\n        SETB    P3.7\n        CLR     P3.7\n        RET\nDMS:    MOV     R7,#248                 ; R6 x 499 + 2 chu kỳ\n        DJNZ    R7,$\n        DJNZ    R6,DMS\n        RET\nMSG:    DB      '4 BIT: P2.4-P2.7',0\n        END\n","note":"Chờ 16 ms, ba lần 30H (một xung E), 20H chuyển sang 4 bit, rồi 28H, 0CH, 06H, 01H mỗi byte hai xung E. 16 ký tự, tổng 24 980 chu kỳ. Theo dõi P2: nửa cao rồi nửa thấp (SWAP A).","dev":{"lcd":true},"fosc":12000000,"speed":"real"},{"label":"Ví dụ: Menu đặt ngưỡng, không chặn","code":"; Ví dụ 5: menu đặt ngưỡng 0…99, vòng chính không chặn.\n; K1 = P3.2 (OK), K2 = P3.3 (LÊN), K3 = P3.4 (XUỐNG).\n; Mỗi nhịp 10 ms (Timer 0): đọc nút. Giữa hai nhịp: nếu LCD\n; rảnh thì gửi MỘT byte của phần cần vẽ lại, không chờ.\n; Dừng khi bấm OK hoặc sau 400 nhịp (để chấm; firmware thật\n; lặp mãi).\n        ORG     0000H\n        CLR     P3.6                    ; RW = 0\n        MOV     A,#38H                  ; khởi tạo: được phép chờ\n        ACALL   LCMD\n        ACALL   W40\n        MOV     A,#0CH\n        ACALL   LCMD\n        ACALL   W40\n        MOV     A,#01H\n        ACALL   LCMD\n        MOV     R6,#4\n        ACALL   DMS                     ; xóa: chờ 2 ms\n        MOV     DPTR,#TXT1\n        ACALL   PUTS                    ; dòng 1\n        MOV     A,#0C0H\n        ACALL   LCMD\n        ACALL   W40\n        MOV     DPTR,#TXT2\n        ACALL   PUTS                    ; dòng 2, cột 0…7\n        MOV     30H,#25                 ; ngưỡng ban đầu (giả định)\n        MOV     31H,#0FFH               ; nút lần trước: đều nhả\n        MOV     32H,#0                  ; 1 = đã bấm OK\n        MOV     34H,#1                  ; bước vẽ: 1 lệnh, 2 chục, 3 đơn vị\n        MOV     TMOD,#01H               ; Timer 0 chế độ 1\n        MOV     TH0,#0D8H               ; 65 536 - 10 000 = D8F0H\n        MOV     TL0,#0F0H\n        SETB    TR0\n        MOV     R4,#4                   ; 4 x 100 nhịp\n        MOV     R5,#100\nMAIN:   JNB     TF0,PUMP                ; chưa tới nhịp: lo LCD\n        CLR     TF0\n        MOV     TH0,#0D8H               ; nạp lại (nhịp dài thêm vài µs)\n        MOV     TL0,#0F0H\n        ACALL   KEYS\n        MOV     A,32H\n        JNZ     STOP                    ; đã bấm OK\n        DJNZ    R5,PUMP\n        MOV     R5,#100\n        DJNZ    R4,PUMP\nSTOP:   CLR     TR0\n        SJMP    $\n; ---- gửi một byte nếu có việc và LCD rảnh ----\nPUMP:   MOV     A,34H\n        JZ      MAIN                    ; không có gì cần vẽ\n        ACALL   BUSY\n        JC      MAIN                    ; LCD bận: để vòng sau\n        MOV     A,34H\n        CJNE    A,#1,PDIG\n        MOV     A,#0C8H                 ; dòng 2, cột 8\n        ACALL   LCMD\n        SJMP    PNXT\nPDIG:   MOV     R2,A\n        MOV     A,30H\n        MOV     B,#10\n        DIV     AB                      ; A = chục, B = đơn vị\n        CJNE    R2,#3,PPUT\n        MOV     A,B\nPPUT:   ADD     A,#'0'\n        ACALL   LDAT\nPNXT:   INC     34H\n        MOV     A,34H\n        CJNE    A,#4,MAIN\n        MOV     34H,#0                  ; vẽ xong\n        SJMP    MAIN\n; ---- nút: sự kiện = lần trước 1, lần này 0 ----\nKEYS:   MOV     A,P3\n        MOV     R2,A\n        CPL     A\n        ANL     A,31H                   ; bit = 1: vừa bấm\n        MOV     31H,R2\n        JNB     ACC.2,KUP\n        MOV     32H,#1                  ; OK\nKUP:    JNB     ACC.3,KDN\n        MOV     R3,A\n        MOV     A,30H\n        CJNE    A,#99,KINC\n        SJMP    KUP2                    ; đã tối đa\nKINC:   INC     30H\n        MOV     34H,#1                  ; vẽ lại\nKUP2:   MOV     A,R3\nKDN:    JNB     ACC.4,KEND\n        MOV     A,30H\n        JZ      KEND                    ; đã tối thiểu\n        DEC     30H\n        MOV     34H,#1\nKEND:   RET\n; ---- LCD 8 bit: đọc BF một lần; C = BF ----\nBUSY:   MOV     P2,#0FFH\n        CLR     P3.5\n        SETB    P3.6                    ; RW = 1\n        SETB    P3.7\n        MOV     A,P2\n        CLR     P3.7\n        CLR     P3.6\n        RLC     A                       ; C = D7 = BF\n        RET\nPUTS:   CLR     A\n        MOVC    A,@A+DPTR\n        JZ      PEND\n        ACALL   LDAT\n        ACALL   W40\n        INC     DPTR\n        SJMP    PUTS\nPEND:   RET\nLCMD:   CLR     P3.5\n        SJMP    LWR\nLDAT:   SETB    P3.5\nLWR:    MOV     P2,A\n        SETB    P3.7\n        CLR     P3.7\n        RET\nW40:    MOV     R7,#20                  ; 43 chu kỳ kể cả RET\n        DJNZ    R7,$\n        RET\nDMS:    MOV     R7,#248\n        DJNZ    R7,$\n        DJNZ    R6,DMS\n        RET\nTXT1:   DB      'DAT NGUONG 0-99',0\nTXT2:   DB      'GIA TRI:',0\n        END\n","note":"Nhịp 10 ms đọc nút; giữa các nhịp, nếu ô 34H ≠ 0 và LCD rảnh thì gửi một byte. Bấm K2/K3 để đổi số, giữ nút chỉ đổi 1; K1 dừng. Không bấm gì: dừng sau 400 nhịp (khoảng 4 s).","dev":{"lcd":true,"btn":{"pins":["P3.2","P3.3","P3.4"],"names":["K1 OK","K2 LÊN","K3 XUỐNG"]}},"fosc":12000000,"speed":"real"}];
const sim40=makeSim51(document.getElementById("m51-l40"),{id:"s40",presets:PR40,ram:256});
makeEx51(document.getElementById("ex-l40"),"l40",[{"t":"Lệnh đặt con trỏ theo dòng và cột","d":"<p>LCD 16×2: dòng 0 dùng địa chỉ DDRAM 00H…0FH, dòng 1 dùng 40H…4FH. Lệnh đặt địa chỉ DDRAM là byte có bit 7 = 1 và 7 bit thấp là địa chỉ. Ô <code>30H<\/code> chứa số dòng, ô <code>31H<\/code> chứa số cột (đếm từ 0). Ghi byte lệnh vào ô <code>32H<\/code>; nếu dòng &gt; 1 hoặc cột &gt; 15 (ngoài màn hình) thì ghi <code>00H<\/code> để báo lỗi. Ô <code>30H<\/code>, <code>31H<\/code> giữ nguyên. Kết thúc bằng <code>SJMP $<\/code>.<\/p><p>Ví dụ: <code>30H = 01H<\/code>, <code>31H = 05H<\/code> → <code>32H = C5H<\/code>.<\/p>","start":"        ORG     0000H\n        MOV     A,31H                   ; cột\n        ADD     A,#80H                  ; (chưa đúng: thiếu dòng, chưa kiểm phạm\n                                        ; vi)\n        MOV     32H,A\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":1,"0x31":5,"0x32":238}},"expect":{"iram":{"0x30":1,"0x31":5,"0x32":197}}},{"setup":{"iram":{"0x30":0,"0x31":0,"0x32":238}},"expect":{"iram":{"0x30":0,"0x31":0,"0x32":128}}},{"setup":{"iram":{"0x30":1,"0x31":0,"0x32":238}},"expect":{"iram":{"0x30":1,"0x31":0,"0x32":192}}},{"setup":{"iram":{"0x30":0,"0x31":15,"0x32":238}},"expect":{"iram":{"0x30":0,"0x31":15,"0x32":143}}},{"setup":{"iram":{"0x30":1,"0x31":15,"0x32":238}},"expect":{"iram":{"0x30":1,"0x31":15,"0x32":207}}},{"setup":{"iram":{"0x30":2,"0x31":3,"0x32":238}},"expect":{"iram":{"0x30":2,"0x31":3,"0x32":0}}},{"setup":{"iram":{"0x30":0,"0x31":16,"0x32":238}},"expect":{"iram":{"0x30":0,"0x31":16,"0x32":0}}}]},"hints":["Code mẫu chỉ cộng cột với 80H: đúng ở dòng 0, sai ở dòng 1 (thiếu 40H) và không kiểm phạm vi.","Kiểm “nhỏ hơn” bằng CJNE A,#2,nhãn ngay dòng sau: CY = 1 khi A &lt; 2. JNC nhảy tới chỗ ghi 00H.","Địa chỉ DDRAM = 80H OR (40H × dòng) OR cột; tìm cách có 40H × dòng với dòng 0 hoặc 1."],"why":"Mọi lệnh “đi tới ô (dòng, cột)” của driver LCD đều là một byte 80H + địa chỉ. Kiểm phạm vi ở driver giúp lỗi tính toán ở tầng menu không ghi chữ ra vùng DDRAM không hiện (ví dụ cột 16 trở đi của dòng 0 nằm ở 10H…27H, không thấy trên màn hình 16 cột)."},{"t":"Một bước của menu đặt ngưỡng","d":"<p>Vòng chính đọc nút mỗi nhịp 10 ms. Ô <code>30H<\/code> là ngưỡng (0–99), ô <code>31H<\/code> là trạng thái nút đọc ở nhịp trước, ô <code>32H<\/code> là trạng thái nút đọc ở nhịp này: bit 3 = LÊN, bit 4 = XUỐNG, mức 0 = đang bấm, các bit khác không dùng. Chỉ tính <b>sự kiện bấm<\/b>: bit đó trước là 1, nay là 0 (giữ nút không tính lại). Xử lý:<\/p><ul><li>chỉ có sự kiện LÊN: tăng 1 nếu ngưỡng &lt; 99;<\/li><li>chỉ có sự kiện XUỐNG: giảm 1 nếu ngưỡng &gt; 0;<\/li><li>cả hai cùng lúc hoặc không có: không đổi.<\/li><\/ul><p>Sau đó ghi <code>31H<\/code> = <code>32H<\/code> (cho nhịp sau), ghi <code>33H = 01H<\/code> nếu ngưỡng đã đổi (cần vẽ lại LCD), ngược lại <code>00H<\/code>. Ô <code>32H<\/code> giữ nguyên. Kết thúc bằng <code>SJMP $<\/code>.<\/p><p>Ví dụ: <code>30H = 25<\/code>, <code>31H = FFH<\/code>, <code>32H = F7H<\/code> (vừa bấm LÊN) → <code>30H = 26<\/code>, <code>31H = F7H<\/code>, <code>33H = 01H<\/code>.<\/p>","start":"        ORG     0000H\n        MOV     33H,#0\n        MOV     A,32H                   ; (chưa đúng: xét mức 0, chưa xét sườn)\n        JB      ACC.3,NOUP\n        INC     30H                     ; (chưa chặn ở 99)\n        MOV     33H,#1\nNOUP:   JB      ACC.4,NODN\n        MOV     A,30H\n        JZ      NODN\n        DEC     30H\n        MOV     33H,#1\nNODN:   MOV     31H,32H\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":25,"0x31":255,"0x32":247,"0x33":238}},"expect":{"iram":{"0x30":26,"0x31":247,"0x32":247,"0x33":1}}},{"setup":{"iram":{"0x30":25,"0x31":247,"0x32":247,"0x33":238}},"expect":{"iram":{"0x30":25,"0x31":247,"0x32":247,"0x33":0}}},{"setup":{"iram":{"0x30":99,"0x31":255,"0x32":247,"0x33":238}},"expect":{"iram":{"0x30":99,"0x31":247,"0x32":247,"0x33":0}}},{"setup":{"iram":{"0x30":0,"0x31":255,"0x32":239,"0x33":238}},"expect":{"iram":{"0x30":0,"0x31":239,"0x32":239,"0x33":0}}},{"setup":{"iram":{"0x30":40,"0x31":255,"0x32":239,"0x33":238}},"expect":{"iram":{"0x30":39,"0x31":239,"0x32":239,"0x33":1}}},{"setup":{"iram":{"0x30":40,"0x31":255,"0x32":231,"0x33":238}},"expect":{"iram":{"0x30":40,"0x31":231,"0x32":231,"0x33":0}}},{"setup":{"iram":{"0x30":40,"0x31":247,"0x32":255,"0x33":238}},"expect":{"iram":{"0x30":40,"0x31":255,"0x32":255,"0x33":0}}},{"setup":{"iram":{"0x30":40,"0x31":255,"0x32":251,"0x33":238}},"expect":{"iram":{"0x30":40,"0x31":251,"0x32":251,"0x33":0}}}]},"hints":["Code mẫu xét mức (bit = 0) nên giữ nút là tăng mãi, và không chặn ở 99.","Sự kiện = (NOT nay) AND trước: CPL A rồi ANL A,31H, sau đó ANL A,#18H chỉ giữ hai bit cần.","Sau khi lọc chỉ còn vài khả năng: rẽ nhánh theo từng giá trị."],"why":"Phát hiện sườn biến “nút đang được giữ” thành “một lần bấm”, nên menu không chạy vùn vụt khi người dùng giữ nút. Cờ “cần vẽ lại” tách logic khỏi LCD: tầng hiển thị chỉ gửi byte khi có thay đổi, vòng chính không bị chặn bởi LCD."},{"t":"Hai nửa byte cho LCD 4 bit, ≤ 14 chu kỳ","d":"<p>LCD chế độ 4 bit nối D4…D7 vào P2.4…P2.7; P2.0…P2.3 đang điều khiển một thiết bị khác nên mỗi lần ghi P2 phải giữ nguyên 4 bit thấp hiện tại. Ô <code>30H<\/code> là byte cần gửi, ô <code>31H<\/code> là giá trị P2 hiện tại. Tính hai giá trị sẽ ghi ra P2: <code>32H<\/code> = nửa cao của byte (ở P2.4…P2.7) + 4 bit thấp của P2; <code>33H<\/code> = nửa thấp của byte đưa lên P2.4…P2.7 + 4 bit thấp của P2. Ô <code>30H<\/code>, <code>31H<\/code> phải giữ nguyên khi dừng. Code mẫu đúng nhưng chạy 20 chu kỳ, dài 30 byte. Hãy viết lại để chạy <b>không quá 14 chu kỳ máy<\/b> (tính cả <code>SJMP $<\/code>), dài <b>không quá 22 byte<\/b>.<\/p><p>Ví dụ: <code>30H = 41H<\/code> (chữ “A”), <code>31H = 0AH<\/code> → <code>32H = 4AH<\/code>, <code>33H = 1AH<\/code>.<\/p>","start":"        ORG     0000H\n        MOV     A,30H                   ; lần 1: nửa cao của byte\n        ANL     A,#0F0H\n        MOV     R2,A\n        MOV     A,31H\n        ANL     A,#0FH                  ; giữ P2.0…P2.3\n        ORL     A,R2\n        MOV     32H,A\n        MOV     A,30H                   ; lần 2: nửa thấp đưa lên cao\n        RL      A\n        RL      A\n        RL      A\n        RL      A\n        ANL     A,#0F0H\n        MOV     R2,A\n        MOV     A,31H\n        ANL     A,#0FH\n        ORL     A,R2\n        MOV     33H,A\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":65,"0x31":10,"0x32":238,"0x33":238}},"expect":{"iram":{"0x30":65,"0x31":10,"0x32":74,"0x33":26}}},{"setup":{"iram":{"0x30":56,"0x31":5,"0x32":238,"0x33":238}},"expect":{"iram":{"0x30":56,"0x31":5,"0x32":53,"0x33":133}}},{"setup":{"iram":{"0x30":255,"0x31":0,"0x32":238,"0x33":238}},"expect":{"iram":{"0x30":255,"0x31":0,"0x32":240,"0x33":240}}},{"setup":{"iram":{"0x30":0,"0x31":255,"0x32":238,"0x33":238}},"expect":{"iram":{"0x30":0,"0x31":255,"0x32":15,"0x33":15}}},{"setup":{"iram":{"0x30":197,"0x31":60,"0x32":238,"0x33":238}},"expect":{"iram":{"0x30":197,"0x31":60,"0x32":204,"0x33":92}}},{"setup":{"iram":{"0x30":1,"0x31":170,"0x32":238,"0x33":238}},"expect":{"iram":{"0x30":1,"0x31":170,"0x32":10,"0x33":26}}}],"maxCyc":14,"maxBytes":22},"hints":["Bốn lần RL A tốn 4 chu kỳ, 4 byte; SWAP A làm cùng việc trong 1 chu kỳ, 1 byte.","Phần “4 bit thấp của P2” giống nhau ở cả hai giá trị: tính một lần, giữ trong R2.","Có một lệnh đổi chỗ 4 bit thấp của A với một ô RAM qua con trỏ (1 chu kỳ); dùng nó thì nhớ trả ô về giá trị cũ."],"why":"Ở chế độ 4 bit, mỗi byte gửi tới LCD là hai lần ghi cổng; nếu ghi thẳng A ra P2 thì thiết bị ở P2.0…P2.3 bị đổi theo. Cách SWAP + ANL/ORL vừa đủ 14 chu kỳ, 22 byte; cách dùng XCHD chỉ 11 chu kỳ, 15 byte vì lệnh này ghép 4 bit thấp mà không cần mặt nạ."}]);

makeQuiz("quiz40","score40",[{"q": "Muốn ghi ký tự vào dòng thứ hai, cột 5 (đếm từ 0) của LCD 16×2, gửi lệnh nào?", "o": ["85H", "C5H", "45H", "D5H"], "a": 1, "e": "Dòng 2 bắt đầu ở địa chỉ DDRAM 40H; lệnh đặt địa chỉ = 80H + 40H + 5 = C5H. 85H là dòng 1 cột 5; 45H thiếu bit 7 nên không phải lệnh đặt địa chỉ."}, {"q": "Sau lệnh xóa màn hình 01H, chương trình gửi ngay chuỗi ký tự với chờ 41 µs mỗi byte. Kết quả trên mô hình HD44780?", "o": ["Hiện đủ chuỗi vì mỗi byte đã chờ 41 µs", "LCD tự xếp hàng các byte và hiện sau", "Chỉ ký tự cuối bị mất", "Các ký tự đến khi LCD còn bận (khoảng 1,52 ms) bị bỏ qua"], "a": 3, "e": "Lệnh xóa bận lâu hơn nhiều so với lệnh thường. Byte gửi tới lúc bận bị bỏ qua, không có hàng đợi (ví dụ 2)."}, {"q": "Ở chế độ ghi (RW = 0), LCD chốt byte trên D0…D7 vào lúc nào?", "o": ["Ở sườn xuống của E", "Ở sườn lên của E", "Khi RS đổi mức", "Ngay khi P2 đổi giá trị"], "a": 0, "e": "Byte và RS phải ổn định trước; LCD lấy byte khi E từ 1 về 0. Vì vậy thứ tự là RS → dữ liệu → SETB E → CLR E."}, {"q": "Ở chế độ 4 bit, gửi một byte lệnh (sau khi đã chuyển sang 4 bit) cần bao nhiêu xung E và nửa nào gửi trước?", "o": ["1 xung, cả byte", "2 xung, nửa thấp trước", "2 xung, nửa cao trước", "4 xung, mỗi xung 2 bit"], "a": 2, "e": "D4…D7 mang nửa cao rồi nửa thấp, mỗi nửa một xung E. Riêng các lần 3xH và 20H khi LCD còn ở 8 bit chỉ là một xung."}, {"q": "Vì sao vòng đọc cờ bận BF cần giới hạn số lần đọc?", "o": ["Không có LCD hoặc LCD hỏng thì chân P2 kéo lên đọc FFH, BF = 1 mãi và chương trình treo", "Vì đọc BF làm LCD chậm lại", "Vì BF chỉ đúng ở lần đọc đầu", "Vì 8051 không đọc được P2 quá 256 lần"], "a": 0, "e": "Điện trở kéo lên làm chân đọc 1 khi không có gì kéo xuống. Có giới hạn thì firmware báo lỗi thay vì đứng (ví dụ 3: 32H = 01H)."}]);

fillSnips();
